UPDATE inv_cost_balance SET cost_quantity=#{costQuantity},cost_amount_minor=#{costAmountMinor},
  avg_unit_cost_minor=#{averageUnitCostMinor},last_unit_cost_minor=#{lastUnitCostMinor},
  last_cost_ledger_sequence=#{lastCostLedgerSequence},last_inventory_ledger_sequence=#{lastInventoryLedgerSequence},
  policy_version_id=#{policyVersionId},record_version=record_version+1,updated_at=#{updatedAt}
WHERE tenant_id=#{tenantId} AND cost_dimension_key=#{costDimensionKey} AND record_version=#{expectedVersion}

UPDATE inv_cost_balance SET cost_quantity=#{costQuantity},cost_amount_minor=#{costAmountMinor},
  avg_unit_cost_minor=#{averageUnitCostMinor},last_unit_cost_minor=#{lastUnitCostMinor},
  last_cost_ledger_sequence=#{lastCostLedgerSequence},last_inventory_ledger_sequence=#{lastInventoryLedgerSequence},
  policy_version_id=#{policyVersionId},record_version=record_version+1,updated_at=#{updatedAt}
WHERE tenant_id=#{tenantId} AND cost_dimension_key=#{costDimensionKey} AND record_version=#{expectedVersion}

mapper.select:
SELECT  FROM inv_cost_ledger
WHERE tenant_id=#{tenantId} AND warehouse_id=#{warehouseId} AND sku_id=#{skuId}
  AND source_type=#{sourceType} AND source_line_id=#{sourceLineId} AND movement_type=#{movementType}
ORDER BY cost_ledger_sequence ASC LIMIT 1

SELECT  FROM inv_cost_ledger
WHERE tenant_id=#{tenantId} AND cost_dimension_key=#{costDimensionKey}
  AND cost_ledger_sequence>#{afterSequence}
ORDER BY cost_ledger_sequence ASC LIMIT #{limit}
